"""Live Eval case schema. Human Gold is never generated by a model.

Default Human Gold (the only annotation template):

    Disposition × Update(Operation, Target) × DeltaContent

SCAN / LEARN / REASON / CREATE are internal interpretations of disposition.
They are not independent annotation fields.
"""

from __future__ import annotations

from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from eval.live.kernel_snapshot import (
    kernel_snapshot_picker,
    resolve_snapshot_node_id,
    snapshot_for_fixture,
    snapshot_node_by_id,
)

KERNEL_SNAPSHOT_PICKER = kernel_snapshot_picker("mvp")

GoldStatus = Literal["LABELED", "UNLABELED"]
SourceKind = Literal[
    "news",
    "paper",
    "technical_blog",
    "field_observation",
    "investment",
    "hype",
    "cross_domain_analogy",
    "wechat",
    "github",
    "company_blog",
]
CognitiveTask = Literal[
    "topic_relevance",
    "structural_relevance",
    "belief_conflict",
    "decision_relevance",
    "evidence_verification",
]

Disposition = Literal["DROP", "AWARE", "WATCH", "ENGAGE"]
UpdateOperation = Literal["REINFORCE", "CHALLENGE", "OPEN_NEW"]

DISPOSITIONS = ("DROP", "AWARE", "WATCH", "ENGAGE")
UPDATE_OPERATIONS = ("REINFORCE", "CHALLENGE", "OPEN_NEW")

# Internal disposition interpretation only — not part of Human Gold.
DISPOSITION_MODE_HINTS = {
    "DROP": (),
    "AWARE": ("SCAN",),
    "WATCH": ("LEARN",),
    "ENGAGE": ("REASON", "CREATE"),
}

HUMAN_GOLD_TEMPLATE = {
    "disposition": None,  # DROP | AWARE | WATCH | ENGAGE
    "update": {
        "operation": None,  # REINFORCE | CHALLENGE | OPEN_NEW
        "target_node_id": None,  # Kernel Snapshot picker id; required for REINFORCE/CHALLENGE; empty for OPEN_NEW
    },
    "delta_content": "",  # free text: cognitive delta after absorbing, not a source claim
}

_DISPOSITION_RANK = {"ENGAGE": 3, "WATCH": 2, "AWARE": 1, "DROP": 0}


def _blank_to_none(value: str | None) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _pick_disposition(values: list[str]) -> str | None:
    ranked = [v for v in values if v in DISPOSITIONS]
    if not ranked:
        return None
    return max(ranked, key=lambda v: _DISPOSITION_RANK[v])


def _legacy_operation(values: list[str]) -> str | None:
    """Read only the live operations. Retired names (REFINE, NO_MATERIAL_CHANGE) are not mapped."""
    for value in values:
        if str(value).upper() in UPDATE_OPERATIONS:
            return str(value).upper()
    return None


class LiveSource(BaseModel):
    model_config = ConfigDict(extra="ignore")

    type: str | None = None
    title: str | None = None
    url: str | None = None
    local_file: str | None = None
    text: str | None = None


class DynamicsEffectGold(BaseModel):
    """Legacy Dynamics Gold pair. Optional compatibility only — not part of the default template."""

    model_config = ConfigDict(extra="ignore")

    target_kernel: str | None = None
    acceptable_effects: list[str] = Field(default_factory=list)
    effect: str | None = None
    min_change_magnitude: float | None = None
    max_change_magnitude: float | None = None
    max_epistemic_strength: float | None = None
    min_epistemic_strength: float | None = None


class CognitiveUpdate(BaseModel):
    """Single cognitive update: one operation, one Kernel Snapshot target (or none)."""

    model_config = ConfigDict(extra="ignore")

    operation: UpdateOperation | None = None
    target_node_id: str | None = Field(
        default=None,
        description="Kernel Snapshot node id from the fixed picker. Not a topic tag.",
    )

    @field_validator("target_node_id", mode="before")
    @classmethod
    def _normalize_target(cls, value: Any) -> str | None:
        if value is None:
            return None
        return _blank_to_none(str(value))

    @model_validator(mode="after")
    def _operation_target_contract(self) -> CognitiveUpdate:
        self.target_node_id = resolve_snapshot_node_id(self.target_node_id)
        op = self.operation
        if op in ("REINFORCE", "CHALLENGE"):
            if not self.target_node_id:
                raise ValueError(f"{op} requires target_node_id pointing at a Kernel Snapshot node")
            if snapshot_node_by_id(self.target_node_id) is None:
                raise ValueError(
                    f"{op} target_node_id {self.target_node_id!r} is not a Kernel Snapshot node"
                )
        if op == "OPEN_NEW" and self.target_node_id:
            raise ValueError("OPEN_NEW requires target_node_id to be empty / null")
        return self


class HumanGold(BaseModel):
    """Disposition × Update × DeltaContent. Legacy keys are mapped, not annotated."""

    model_config = ConfigDict(extra="ignore")

    disposition: Disposition | None = Field(
        default=None,
        description="DROP | AWARE | WATCH | ENGAGE",
    )
    update: CognitiveUpdate | None = Field(default=None)
    delta_content: str | None = Field(
        default=None,
        description="Cognitive delta after absorbing this information — not a source claim or evidence quote.",
    )

    # Legacy optional — readable via compatibility layer, excluded from dump / default template.
    attention_state: list[str] = Field(default_factory=list, exclude=True)
    processing_modes: list[str] = Field(default_factory=list, exclude=True)
    kernel_targets: list[str] = Field(default_factory=list, exclude=True)
    cognitive_effects: list[str] = Field(default_factory=list, exclude=True)
    expected_delta: str | None = Field(default=None, exclude=True)
    acceptable_modes: list[str] = Field(default_factory=list, exclude=True)
    must_match_kernel: list[str] = Field(default_factory=list, exclude=True)
    should_match_kernel: list[str] = Field(default_factory=list, exclude=True)
    forbidden_kernel: list[str] = Field(default_factory=list, exclude=True)
    key_claims: list[str] = Field(default_factory=list, exclude=True)
    key_observations: list[str] = Field(default_factory=list, exclude=True)
    expected_delta_concepts: list[str] = Field(default_factory=list, exclude=True)
    forbidden_conclusions: list[str] = Field(default_factory=list, exclude=True)
    expected_effects: list[DynamicsEffectGold] = Field(default_factory=list, exclude=True)
    forbidden_effects: list[DynamicsEffectGold] = Field(default_factory=list, exclude=True)
    delta_rubric: int | None = Field(default=None, ge=0, le=3, exclude=True)
    notes: str | None = Field(default=None, exclude=True)

    @model_validator(mode="before")
    @classmethod
    def _promote_legacy(cls, data: Any) -> Any:
        if not isinstance(data, dict):
            return data
        data = dict(data)
        if not data.get("processing_modes") and data.get("acceptable_modes"):
            data["processing_modes"] = list(data.get("acceptable_modes") or [])
        if not data.get("kernel_targets"):
            if data.get("must_match_kernel"):
                data["kernel_targets"] = list(data.get("must_match_kernel") or [])
            elif data.get("expected_effects"):
                data["kernel_targets"] = [
                    (item.get("target_kernel") if isinstance(item, dict) else getattr(item, "target_kernel", None))
                    or ""
                    for item in (data.get("expected_effects") or [])
                ]
        if not data.get("cognitive_effects") and data.get("expected_effects"):
            kinds: list[str] = []
            for item in data.get("expected_effects") or []:
                if isinstance(item, dict):
                    kinds.extend(item.get("acceptable_effects") or [])
                    if item.get("effect"):
                        kinds.append(item["effect"])
                else:
                    kinds.extend(getattr(item, "acceptable_effects", None) or [])
                    effect = getattr(item, "effect", None)
                    if effect:
                        kinds.append(effect)
            data["cognitive_effects"] = kinds
        if not data.get("delta_content"):
            data["delta_content"] = data.get("expected_delta") or None
            if not data["delta_content"] and data.get("expected_delta_concepts"):
                joined = "; ".join(s for s in data["expected_delta_concepts"] if s)
                data["delta_content"] = joined or None
        if not data.get("disposition"):
            states = [str(s) for s in (data.get("attention_state") or []) if s]
            data["disposition"] = _pick_disposition(states)
            if not data["disposition"]:
                modes = {str(m).upper() for m in (data.get("processing_modes") or []) if m}
                if modes & {"VERIFY", "DEEP_DIVE", "SYNTHESIZE", "REASON", "CREATE"}:
                    data["disposition"] = "ENGAGE"
                elif "LEARN" in modes:
                    data["disposition"] = "WATCH"
                elif "SCAN" in modes:
                    data["disposition"] = "AWARE"
        if "update" not in data:
            effects = [str(e) for e in (data.get("cognitive_effects") or []) if e]
            operation = _legacy_operation(effects)
            targets = [t for t in (data.get("kernel_targets") or []) if t]
            named = [t for t in targets if str(t).upper() != "NONE"]
            raw_target = named[0] if named else None
            if operation == "OPEN_NEW":
                # New contract: OPEN_NEW cannot carry a snapshot target.
                data["update"] = {"operation": "OPEN_NEW", "target_node_id": None}
            elif operation in {"REINFORCE", "CHALLENGE"}:
                target_id = resolve_snapshot_node_id(raw_target)
                if target_id and snapshot_node_by_id(target_id) is not None:
                    data["update"] = {"operation": operation, "target_node_id": target_id}
                # Otherwise leave update unset so a legacy row still parses.
        elif isinstance(data.get("update"), dict):
            upd = dict(data["update"])
            if upd.get("target_node_id"):
                upd["target_node_id"] = resolve_snapshot_node_id(upd["target_node_id"])
            data["update"] = upd
        return data

    def has_core_labels(self) -> bool:
        update = self.update
        return bool(
            self.disposition
            or (update and update.operation)
            or (self.delta_content or "").strip()
        )

    def has_legacy_labels(self) -> bool:
        return bool(
            self.attention_state
            or self.processing_modes
            or self.kernel_targets
            or self.cognitive_effects
            or (self.expected_delta or "").strip()
            or self.must_match_kernel
            or self.key_claims
            or self.key_observations
            or self.expected_effects
            or self.acceptable_modes
            or self.expected_delta_concepts
        )


class FrozenDelta(BaseModel):
    """Frozen canonical Δ for Oracle-Δ Attention Policy eval. Fail loud; no coercion."""

    model_config = ConfigDict(extra="forbid")

    operation: UpdateOperation | None = None
    target_node_id: str | None = None
    target_type: str | None = Field(
        default=None,
        description="BELIEF | MODEL | QUESTION | DECISION | BOTTLENECK | PROJECT | …",
    )
    change_magnitude: float | None = Field(default=None, ge=0, le=1)
    epistemic_strength: float | None = Field(default=None, ge=0, le=1)
    target_importance: float | None = Field(default=None, ge=0, le=1)
    reason: str | None = None

    @model_validator(mode="after")
    def _fail_loud(self) -> FrozenDelta:
        op = self.operation
        has_target = self.target_node_id is not None
        has_type = self.target_type is not None
        has_mags = any(
            v is not None
            for v in (self.change_magnitude, self.epistemic_strength, self.target_importance)
        )
        has_reason = self.reason is not None and str(self.reason).strip() != ""
        if op is None:
            if has_target or has_type or has_mags or has_reason:
                raise ValueError("operation=null FrozenDelta cannot carry target or magnitude fields")
            return self
        missing = [
            name
            for name, value in (
                ("change_magnitude", self.change_magnitude),
                ("epistemic_strength", self.epistemic_strength),
                ("target_importance", self.target_importance),
            )
            if value is None
        ]
        if missing:
            raise ValueError(f"{op} FrozenDelta requires {', '.join(missing)}")
        if op in ("REINFORCE", "CHALLENGE"):
            if not self.target_node_id:
                raise ValueError(f"{op} requires target_node_id")
            if not self.target_type:
                raise ValueError(f"{op} requires target_type")
        if op == "OPEN_NEW":
            if self.target_node_id is not None:
                raise ValueError("OPEN_NEW requires target_node_id to be null")
            if self.target_type is not None:
                raise ValueError("OPEN_NEW requires target_type to be null")
        return self


def is_complete_positive_frozen_delta(frozen: FrozenDelta | None) -> bool:
    """True only when FrozenDelta fully specifies a positive Δ for Oracle-Δ scoring."""
    if frozen is None or frozen.operation is None:
        return False
    if any(
        value is None
        for value in (frozen.change_magnitude, frozen.epistemic_strength, frozen.target_importance)
    ):
        return False
    if frozen.operation in ("REINFORCE", "CHALLENGE"):
        return bool(frozen.target_node_id and frozen.target_type)
    if frozen.operation == "OPEN_NEW":
        return frozen.target_node_id is None and frozen.target_type is None
    return False


def gold_update_operation(gold: HumanGold | None) -> str | None:
    if gold is None or gold.update is None:
        return None
    return gold.update.operation


def gold_has_explicit_none_update(gold: HumanGold | None) -> bool:
    """True only when Human Gold explicitly set update: null (not omitted)."""
    if gold is None:
        return False
    return "update" in gold.model_fields_set and gold.update is None


def gold_update_target(gold: HumanGold | None) -> str | None:
    if gold is None or gold.update is None:
        return None
    return resolve_snapshot_node_id(gold.update.target_node_id)


def assert_gold_frozen_consistent(gold: HumanGold | None, frozen: FrozenDelta | None) -> None:
    """Fail loud when HumanGold.update and FrozenDelta disagree on operation/target."""
    if gold is None or frozen is None:
        return
    gold_op = gold_update_operation(gold)
    gold_tgt = gold_update_target(gold)
    frozen_tgt = resolve_snapshot_node_id(frozen.target_node_id)
    if gold_op is None and frozen.operation is None:
        return
    if gold_op != frozen.operation:
        raise ValueError(
            f"HumanGold.update.operation {gold_op!r} does not match FrozenDelta.operation {frozen.operation!r}"
        )
    if gold_op in ("REINFORCE", "CHALLENGE") and gold_tgt != frozen_tgt:
        raise ValueError(
            f"HumanGold.update.target_node_id {gold_tgt!r} does not match FrozenDelta.target_node_id {frozen_tgt!r}"
        )
    if gold_op == "OPEN_NEW" and (gold_tgt is not None or frozen_tgt is not None):
        raise ValueError("OPEN_NEW gold/frozen target_node_id must both be null")


def assert_frozen_delta_matches_snapshot(frozen: FrozenDelta | None, fixture: str | None) -> None:
    """Fail loud when FrozenDelta target id/type disagrees with the case snapshot."""
    if frozen is None or frozen.operation is None:
        return
    snapshot_for_fixture(fixture)
    if frozen.operation == "OPEN_NEW":
        return
    node = snapshot_node_by_id(frozen.target_node_id, fixture=fixture)
    if node is None:
        raise ValueError(
            f"FrozenDelta target_node_id {frozen.target_node_id!r} is not in kernel_fixture {fixture or 'mvp'!r}"
        )
    if frozen.target_type != node.node_type:
        raise ValueError(
            f"FrozenDelta target_type {frozen.target_type!r} does not match snapshot "
            f"{node.id} type {node.node_type!r} in kernel_fixture {fixture or 'mvp'!r}"
        )


class PolicyRuntime(BaseModel):
    """RuntimeContext fields that Attention Policy may overlay. Not Δ."""

    model_config = ConfigDict(extra="ignore")

    current_task: str | None = None
    session_topic: str | None = None
    available_attention_minutes: int | None = None
    interruptibility: str | None = None
    cognitive_capacity: str | None = None
    deadline_minutes: float | None = None


class LiveCase(BaseModel):
    model_config = ConfigDict(extra="ignore")

    id: str
    source: LiveSource = Field(default_factory=LiveSource)
    kernel_fixture: str | None = "mvp"
    source_kind: SourceKind | None = None
    cognitive_tasks: list[CognitiveTask] = Field(default_factory=list)
    human_gold: HumanGold | None = None
    gold_status: GoldStatus = "UNLABELED"
    notes: str | None = None
    frozen_delta: FrozenDelta | None = None
    runtime_context: PolicyRuntime | None = None

    @model_validator(mode="after")
    def _gold_frozen_consistent(self) -> LiveCase:
        assert_gold_frozen_consistent(self.human_gold, self.frozen_delta)
        assert_frozen_delta_matches_snapshot(self.frozen_delta, self.kernel_fixture)
        return self


class LiveManifest(BaseModel):
    model_config = ConfigDict(extra="ignore")

    name: str = "raos-live-eval"
    cases: list[LiveCase] = Field(default_factory=list)


def gold_status_of(case: LiveCase) -> GoldStatus:
    if case.gold_status == "LABELED":
        return "LABELED"
    gold = case.human_gold
    if gold is None:
        return "UNLABELED"
    if gold.has_core_labels() or gold.has_legacy_labels():
        return "LABELED"
    return "UNLABELED"


def dump_human_gold(gold: HumanGold | None) -> dict[str, Any] | None:
    """Persist only the default 3-block contract. Legacy keys are mapped on read, never dumped."""
    if gold is None:
        return None
    update = gold.update
    return {
        "disposition": gold.disposition,
        "update": {
            "operation": update.operation if update else None,
            "target_node_id": update.target_node_id if update else None,
        },
        "delta_content": gold.delta_content,
    }
